  exit_codes: Record<string, string>;
  examples: string[];
}

export interface CapabilitiesManifest {
  version: string;
  commands: CommandCapability[];
  intelligence: {
    mechanical: boolean;
    heuristic: boolean;
    llm: { available: boolean; via: "api" | "delegate" };
  };
}

const EXIT_CODES = {
  "0": "clean — no issues found",
  "1": "issues found",
